    const sec = (title, rows, head) => rows.length ? `<div class="pink-label">${esc(title)} (${rows.length})</div><div class="tbl-wrap"><table class="tbl"><thead><tr>${head.map(h => `<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>` : '';
